#include <iostream>
#include <string>

int main() {
    auto* names = new std::string[3];   // 3 default-constructed strings
    names[0] = "AAPL";
    names[1] = "MSFT";
    names[2] = "GOOG";
    delete[] names;                     // destroys all 3 strings, then frees

    auto* s = new std::string("fill@15:00:05");
    std::cout << s->size() << '\n';     // 13
    delete s;
}

#include <iostream>
#include <new>

int main() {
    // 4 GB request - plausible to fail on a constrained machine
    int* big = new (std::nothrow) int[1000000000];
    if (big == nullptr) {
        std::cout << "allocation failed, program continues\n";
    } else {
        std::cout << "allocation succeeded\n";
        delete[] big;
    }
}

guidedExercise.prompt:
Consider this function, called on the hot path:

```cpp
double* process(std::size_t n) {
    double* buf = new double[n];
    fill_from_feed(buf, n);      // may throw on feed errors
    return buf;
}
```

(a) Who owns the returned buffer - and how would you document that? (b) Exactly what happens if fill_from_feed throws? (c) Can a raw new/delete pair inside this function be made exception-safe? (d) What is the idiomatic C++ fix?

